<script lang="ts">import { page } from '$app/stores'; import { onMount } from 'svelte'; import { getAsset } from '$lib/services/api/assets'; import AssetForm from '$lib/components/crud/AssetForm.svelte'; let asset:any=null; onMount(async()=>{ const r=await getAsset($page.params.id as string); if(r.success) asset=r.data; });</script><div class="space-y-4"><h1 class="text-2xl font-bold">Edit Aset</h1>{#if asset}<AssetForm {asset}/>{:else}<div class="card">Memuat...</div>{/if}</div>